﻿@*
<summary>
BovisContextView is a component that enables it child content when the filter conditions are met.
It knows about the current HttpContext and the current User and Group and can be used to filter content on this infos.
The filter conditions are defined by the Expr and Filter parameters.
The Expr parameter is a string that represents a runtime boolean expression.
The Filter parameter is a lambda or delegate which receives a UserContext parameter.
</summary>
*@
@using Microsoft.AspNetCore.Http
@using System.Diagnostics.CodeAnalysis
@inject IHttpContextAccessor ContextAccessor

@if (Pass)
{
    @ChildContent
}

@code {

    /// <summary>
    /// A boolean expression that is evaluated at runtime.
    /// </summary>
    [Parameter]
    public string Expr { get; set; } = "true";

    /// <summary>
    /// A delegate that is called with a UserContext parameter to check the filter condition.
    /// </summary>
    [Parameter]
    public Func<UserContext,bool>? Filter { get; set; }=null;

    [Parameter]
    public RenderFragment? ChildContent { get; set; }

    [MemberNotNull(nameof(userContext))]
    protected override void OnInitialized()
    {
        userContext = new UserContext(this.ContextAccessor.HttpContext); // Initialize the user field in the OnInitialized method
    }

    private UserContext userContext { get; set; } = null!;
    //private string currentUser => userContext.CurrentUser; // Change the getter to a lambda expression
    //private string currentGroup => userContext.CurrentGroup;
    private bool Pass => Util.AuthFilterExpression.Eval(Expr,userContext) && (Filter!=null?Filter(userContext) :true);
}
