@using Microsoft.AspNetCore.Http
@using System.Diagnostics.CodeAnalysis
@inject IHttpContextAccessor ContextAccessor

@if (Globals.UseInternalAuth)
{
    @userContext.CurrentGroup
}
else
{
    <AuthorizeView>
        <Authorized>
            <a href="Identity/Account/Manage">Hello, @context.User.Identity?.Name!</a>
            <form method="post" action="Identity/Account/Logout">
                <button type="submit" class="nav-link btn btn-link">Log out</button>
            </form>
        </Authorized>
        <NotAuthorized>
            <a href="Identity/Account/Register">Register</a>
            <a href="Identity/Account/Login">Log in</a>
        </NotAuthorized>
    </AuthorizeView>
}

@code {

    [MemberNotNull(nameof(userContext))]
    protected override void OnInitialized()
    {
        userContext = new UserContext(this.ContextAccessor.HttpContext); // Initialize the user field in the OnInitialized method
    }

    private UserContext userContext { get; set; } = null!;
}
